style.css:
@-moz-document url-prefix("https://www.roblox.com/pl/games/4924922222/Brookhaven-RP") {
/* Tło całej strony: gradient niebieski */
  body {
    background: linear-gradient(135deg, #1E90FF, #00BFFF) !important;
    color: white !important;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif !important;
  }

  /* Centralny nagłówek z napisem "Brookhaven" */
  .game-main-content::before {
    content: "? Brookhaven";
    display: block;
    text-align: center;
    font-size: 56px;
    font-weight: bold;
    color: white;
    padding: 40px 0 20px;
    background: transparent;
    text-shadow: 2px 2px 6px rgba(0, 0, 0, 0.4);
  }

  /* Ukryj oryginalny tytuł gry */
  h1.game-name {
    display: none !important;
  }

  /* Ustaw przezroczystość i lekki cień dla kontenera gry */
  .game-main-content {
    background-color: rgba(0, 0, 0, 0.3) !important;
    padding: 20px;
    border-radius: 12px;
    box-shadow: 0 0 12px rgba(0, 0, 0, 0.3);
  }

  /* Dostosuj przyciski (np. Graj) */
  .btn-common-play-game-lg {
    background-color: #007BFF !important;
    border: none !important;
    color: white !important;
    font-weight: bold;
    border-radius: 8px !important;
    transition: background-color 0.3s ease;
  }

  .btn-common-play-game-lg:hover {
    background-color: #0056b3 !important;
  }

  /* Dostosuj etykiety i teksty */
  .icon-label, .vote-text, .text-label, .text-name, .age-recommendation-title {
    color: white !important;
  }

  /* Ukryj reklamy (opcjonalnie) */
  .ads-container, .game-details-invite-link-expired-modal-container {
    display: none !important;
  }
}
